                    "sql": "CREATE OR REPLACE TABLE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_Sales_Cost_Source_intermediate AS WITH SalesBase AS ( SELECT order_date::date AS date, COALESCE(NULLIF(UPPER(TRIM(brand)),\'\'),\'UNMAPPED\') AS brand, CASE WHEN LOWER(COALESCE(shop_name,marketplace)) LIKE ANY (\'%amazon%\') THEN \'AMAZON\' WHEN LOWER(COALESCE(shop_name,marketplace)) LIKE ANY (\'%shopify%\') THEN \'SHOPIFY\' WHEN LOWER(COALESCE(shop_name,marketplace)) LIKE ANY (\'%pee%\') THEN \'PEE SAFE\' WHEN LOWER(COALESCE(shop_name,marketplace)) LIKE ANY (\'%furr%\') THEN \'FURR\' ELSE UPPER(TRIM(COALESCE(shop_name,marketplace))) END AS marketplace, COALESCE(NULLIF(UPPER(TRIM(channel)),\'\'),\'UNMAPPED\') AS marketing_channel, COALESCE(NULLIF(UPPER(TRIM(source)),\'\'),\'UNMAPPED\') AS source, COALESCE(NULLIF(UPPER(TRIM(type)),\'\'),\'UNMAPPED\') AS channel_type, selling_price, order_status, order_id, new_customer_flag, customer_id_final, discount, tax, shipping_price, quantity, return_flag, dispatch_date, acquisition_date, payment_mode FROM PEESAFE_DB.MAPLEMONK.PEESAFE_DB_SALES_CONSOLIDATED ), SalesGrain AS ( SELECT date, brand, marketplace, marketing_channel, source, channel_type, SUM(GREATEST(IFNULL(selling_price,0),0)) AS allocation_sales, COUNT(DISTINCT CASE WHEN LOWER(new_customer_flag) = \'new\' THEN customer_id_final END) AS new_customers FROM SalesBase GROUP BY 1,2,3,4,5,6 ), ChannelSales AS ( SELECT date, marketplace, marketing_channel, SUM(GREATEST(IFNULL(allocation_sales,0),0)) AS channel_sales, COUNT(*) AS grain_count FROM SalesGrain GROUP BY 1,2,3 ), Allocation AS ( SELECT S.date, S.brand, S.marketplace, S.marketing_channel, S.source, S.channel_type, CASE WHEN C.channel_sales > 0 THEN GREATEST(IFNULL(S.allocation_sales,0),0) / C.channel_sales ELSE 1.0 / C.grain_count END AS allocation_pct FROM SalesGrain S INNER JOIN ChannelSales C ON S.date = C.date AND S.marketplace = C.marketplace AND S.marketing_channel = C.marketing_channel ), Sessions AS ( SELECT date::date AS date, COALESCE(NULLIF(UPPER(TRIM(brand)),\'\'),\'UNMAPPED\') AS brand, CASE WHEN LOWER(shop_name) LIKE ANY (\'%amazon%\') THEN \'AMAZON\' WHEN LOWER(shop_name) LIKE ANY (\'%shopify%\') THEN \'SHOPIFY\' WHEN LOWER(shop_name) LIKE ANY (\'%pee%\') THEN \'PEE SAFE\' WHEN LOWER(shop_name) LIKE ANY (\'%furr%\') THEN \'FURR\' ELSE UPPER(TRIM(shop_name)) END AS marketplace, COALESCE(NULLIF(UPPER(TRIM(channel)),\'\'),\'UNMAPPED\') AS marketing_channel, COALESCE(NULLIF(UPPER(TRIM(source)),\'\'),\'UNMAPPED\') AS source, COALESCE(NULLIF(UPPER(TRIM(type)),\'\'),\'UNMAPPED\') AS channel_type, SUM(IFNULL(sessions,0)) AS sessions, sum(ifnull(transactions,0)) as transactions, sum(ifnull(revenue,0)) as revenue FROM PEESAFE_DB.MAPLEMONK.PEESAFE_DB_ga_sessions_consolidated GROUP BY 1,2,3,4,5,6 ), SpendChannel AS ( SELECT date::date AS date, CASE WHEN LOWER(channel) LIKE ANY (\'%facebook%\',\'%google%\') THEN \'SHOPIFY\' WHEN LOWER(channel) LIKE ANY (\'%amazon%\') THEN \'AMAZON\' WHEN LOWER(channel) LIKE ANY (\'%pee%\') THEN \'PEE SAFE\' WHEN LOWER(channel) LIKE ANY (\'%furr%\') THEN \'FURR\' ELSE \'OTHERS\' END AS marketplace, UPPER(TRIM(channel)) AS marketing_channel, SUM(IFNULL(spend,0)) AS marketing_spend FROM PEESAFE_DB.MAPLEMONK.PEESAFE_DB_MARKETING_CONSOLIDATED GROUP BY 1,2,3 ), SpendAllocated AS ( SELECT A.date, A.brand, A.marketplace, A.marketing_channel, A.source, A.channel_type, S.marketing_spend * A.allocation_pct AS marketing_spend FROM Allocation A INNER JOIN SpendChannel S ON date(A.date) = date(S.date) AND upper(trim(A.marketplace)) = upper(trim(S.marketplace)) AND upper(trim(A.marketing_channel)) = upper(trim(S.marketing_channel)) ), ReturnChannel AS ( SELECT return_date::date AS date, UPPER(TRIM(marketing_channel)) AS marketing_channel, CASE WHEN LOWER(marketplace) LIKE ANY (\'%amazon%\') THEN \'AMAZON\' WHEN LOWER(marketplace) LIKE ANY (\'%shopify%\') THEN \'SHOPIFY\' WHEN LOWER(marketplace) LIKE ANY (\'%pee%\') THEN \'PEE SAFE\' WHEN LOWER(marketplace) LIKE ANY (\'%furr%\') THEN \'FURR\' ELSE UPPER(TRIM(marketplace)) END AS marketplace, SUM(IFNULL(total_return_amount,0)) AS total_return_amount, SUM(IFNULL(total_return_amount_excl_tax,0)) AS total_return_amount_excl_tax, SUM(IFNULL(total_returned_quantity,0)) AS total_returned_quantity FROM PEESAFE_DB.MAPLEMONK.PEESAFE_DB_RETURNS_CONSOLIDATED GROUP BY 1,2,3 ), ReturnAllocated AS ( SELECT A.date, A.brand, A.marketplace, A.marketing_channel, A.source, A.channel_type, R.total_return_amount * A.allocation_pct AS total_return_amount, R.total_return_amount_excl_tax * A.allocation_pct AS total_return_amount_excl_tax, R.total_returned_quantity * A.allocation_pct AS total_returned_quantity FROM Allocation A INNER JOIN ReturnChannel R ON A.date = R.date AND A.marketplace = R.marketplace AND A.marketing_channel = R.marketing_channel ), Orders AS ( SELECT date, brand, marketplace, marketing_channel, source, channel_type, SUM(GREATEST(IFNULL(selling_price,0),0)) AS total_sales, SUM(GREATEST(IFNULL(selling_price,0),0)) - SUM(CASE WHEN LOWER(order_status) = \'cancelled\' THEN GREATEST(IFNULL(selling_price,0),0) END) AS total_sales_excl_cancl, COUNT(DISTINCT order_id) AS total_orders, COUNT(DISTINCT order_id) - COUNT(DISTINCT CASE WHEN LOWER(order_status) = \'cancelled\' THEN order_id END) AS orders_excl_cancl, COUNT(DISTINCT CASE WHEN LOWER(new_customer_flag) = \'new\' THEN order_id END) AS new_customer_orders, COUNT(DISTINCT CASE WHEN LOWER(new_customer_flag) = \'new\' THEN order_id END) - COUNT(DISTINCT CASE WHEN LOWER(new_customer_flag) = \'new\' AND LOWER(order_status) = \'cancelled\' THEN order_id END) AS new_customer_orders_excl_cancl, COUNT(DISTINCT CASE WHEN LOWER(new_customer_flag) = \'new\' THEN customer_id_final END) AS total_new_customers, COUNT(DISTINCT CASE WHEN LOWER(new_customer_flag) = \'new\' THEN customer_id_final END) - COUNT(DISTINCT CASE WHEN LOWER(new_customer_flag) = \'new\' AND LOWER(order_status) = \'cancelled\' AND return_flag = 0 THEN customer_id_final END) AS new_customers_excl_cancl, COUNT(DISTINCT customer_id_final) AS total_unique_customers, COUNT(DISTINCT customer_id_final) - COUNT(DISTINCT CASE WHEN LOWER(order_status) = \'cancelled\' THEN customer_id_final END) AS unique_customers_excl_cancl, COUNT(DISTINCT CASE WHEN LOWER(new_customer_flag) = \'repeat\' THEN customer_id_final END) AS repeat_customers, COUNT(DISTINCT CASE WHEN LOWER(new_customer_flag) = \'repeat\' THEN customer_id_final END) - COUNT(DISTINCT CASE WHEN LOWER(new_customer_flag) = \'repeat\' AND LOWER(order_status) = \'cancelled\' AND return_flag = 0 THEN customer_id_final END) AS repeat_customers_excl_cancl, SUM(IFNULL(discount,0)) AS total_discount, SUM(IFNULL(discount,0)) - SUM(CASE WHEN LOWER(order_status) = \'cancelled\' THEN discount END) AS total_discount_excl_cancl, SUM(IFNULL(tax,0)) AS total_tax, SUM(IFNULL(tax,0)) - SUM(CASE WHEN LOWER(order_status) = \'cancelled\' THEN tax END) AS tax_excl_cancl, SUM(IFNULL(shipping_price,0)) AS total_shipping_price, SUM(IFNULL(shipping_price,0)) - SUM(CASE WHEN LOWER(order_status) = \'cancelled\' THEN shipping_price END) AS shipping_price_excl_cancl, SUM(CASE WHEN LOWER(new_customer_flag) = \'new\' THEN discount END) AS new_customer_discount, SUM(CASE WHEN LOWER(new_customer_flag) = \'new\' THEN discount END) - SUM(CASE WHEN LOWER(new_customer_flag) = \'new\' AND LOWER(order_status) = \'cancelled\' THEN discount END) AS new_customer_discount_excl_cancl, SUM(IFNULL(quantity,0)) AS total_quantity, SUM(IFNULL(quantity,0)) - SUM(CASE WHEN LOWER(order_status) = \'cancelled\' THEN quantity END) AS quantity_excl_cancl, COUNT(DISTINCT CASE WHEN LOWER(order_status) = \'cancelled\' THEN order_id END) AS cancelled_orders, COUNT(DISTINCT CASE WHEN LOWER(order_status) <> \'cancelled\' AND return_flag = 0 THEN order_id END) AS net_orders, COUNT(DISTINCT CASE WHEN LOWER(order_status) = \'delivered\' THEN order_id END) AS delivered_orders, COUNT(DISTINCT CASE WHEN LOWER(order_status) IN (\'returned\',\'rto\') THEN order_id END) AS returned_orders, COUNT(DISTINCT CASE WHEN dispatch_date IS NOT NULL AND LOWER(order_status) <> \'cancelled\' THEN order_id END) AS dispatched_orders, COUNT(DISTINCT CASE WHEN LOWER(order_status) IN (\'shipped\',\'printed\',\'confirmed\',\'returned\',\'ready to dispatch\') THEN order_id END) AS realised_orders, SUM(CASE WHEN LOWER(order_status) = \'delivered\' THEN IFNULL(selling_price,0) - IFNULL(tax,0) END) AS delivered_revenue, SUM(CASE WHEN LOWER(order_status) IN (\'returned\',\'rto\') THEN IFNULL(selling_price,0) - IFNULL(tax,0) END) AS returned_revenue, SUM(CASE WHEN dispatch_date IS NOT NULL AND LOWER(order_status) <> \'cancelled\' THEN IFNULL(selling_price,0) END) AS dispatched_revenue, SUM(CASE WHEN LOWER(order_status) IN (\'shipped\',\'printed\',\'confirmed\',\'returned\',\'ready to dispatch\') THEN IFNULL(selling_price,0) END) AS realised_revenue, COUNT(CASE WHEN DATE_TRUNC(\'month\',acquisition_date) >= DATEADD(month,-3,DATE_TRUNC(\'month\',date)) AND DATE_TRUNC(\'month\',acquisition_date) < DATE_TRUNC(\'month\',date) THEN customer_id_final END) AS l3m_customers_retained, COUNT(CASE WHEN DATE_TRUNC(\'month\',acquisition_date) >= DATEADD(month,-6,DATE_TRUNC(\'month\',date)) AND DATE_TRUNC(\'month\',acquisition_date) < DATE_TRUNC(\'month\',date) THEN customer_id_final END) AS l6m_customers_retained, COUNT(CASE WHEN DATE_TRUNC(\'month\',acquisition_date) >= DATEADD(month,-12,DATE_TRUNC(\'month\',date)) AND DATE_TRUNC(\'month\',acquisition_date) < DATE_TRUNC(\'month\',date) THEN customer_id_final END) AS l12m_customers_retained, SUM(CASE WHEN LOWER(new_customer_flag) = \'repeat\' THEN IFNULL(selling_price,0) END) AS repeat_customer_revenue, COUNT(DISTINCT CASE WHEN LOWER(payment_mode) = \'cod\' THEN order_id END) AS cod_orders FROM SalesBase GROUP BY 1,2,3,4,5,6 ), TillDateGrain AS ( SELECT date, brand, marketplace, marketing_channel, source, channel_type, SUM(allocation_sales) OVER ( PARTITION BY brand, marketplace, marketing_channel, source, channel_type ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS mc_mp_sales_till_date, SUM(new_customers) OVER ( PARTITION BY brand, marketplace, marketing_channel, source, channel_type ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS mc_mp_customer_till_date FROM SalesGrain ), FinalGrain AS ( SELECT date, brand, marketplace, marketing_channel, source, channel_type FROM Orders UNION SELECT date, brand, marketplace, marketing_channel, source, channel_type FROM Sessions UNION SELECT date, brand, marketplace, marketing_channel, source, channel_type FROM SpendAllocated UNION SELECT date, brand, marketplace, marketing_channel, source, channel_type FROM ReturnAllocated ) SELECT G.date, G.brand, G.marketplace, G.marketing_channel, G.source, G.channel_type, IFNULL(O.total_sales,0) AS total_sales, IFNULL(O.total_sales_excl_cancl,0) AS total_sales_excl_cancl, IFNULL(S.sessions,0) AS sessions, ifnull(s.transactions,0) as transactions, ifnull(s.revenue,0) as revenue, IFNULL(O.total_orders,0) AS total_orders, IFNULL(O.orders_excl_cancl,0) AS orders_excl_cancl, IFNULL(O.new_customer_orders,0) AS new_customer_orders, IFNULL(O.new_customer_orders_excl_cancl,0) AS new_customer_orders_excl_cancl, IFNULL(O.total_new_customers,0) AS total_new_customers, IFNULL(O.new_customers_excl_cancl,0) AS new_customers_excl_cancl, IFNULL(O.total_unique_customers,0) AS total_unique_customers, IFNULL(O.unique_customers_excl_cancl,0) AS unique_customers_excl_cancl, IFNULL(O.repeat_customers,0) AS repeat_customers, IFNULL(O.repeat_customers_excl_cancl,0) AS repeat_customers_excl_cancl, IFNULL(O.total_discount,0) AS total_discount, IFNULL(O.total_discount_excl_cancl,0) AS total_discount_excl_cancl, IFNULL(O.total_tax,0) AS total_tax, IFNULL(O.tax_excl_cancl,0) AS tax_excl_cancl, IFNULL(O.total_shipping_price,0) AS total_shipping_price, IFNULL(O.shipping_price_excl_cancl,0) AS shipping_price_excl_cancl, IFNULL(O.new_customer_discount,0) AS new_customer_discount, IFNULL(O.new_customer_discount_excl_cancl,0) AS new_customer_discount_excl_cancl, IFNULL(O.total_quantity,0) AS total_quantity, IFNULL(O.quantity_excl_cancl,0) AS quantity_excl_cancl, IFNULL(R.total_returned_quantity,0) AS return_quantity, IFNULL(R.total_return_amount,0) AS return_value, IFNULL(O.cancelled_orders,0) AS cancelled_orders, IFNULL(O.net_orders,0) AS net_orders, IFNULL(O.delivered_orders,0) AS delivered_orders, IFNULL(O.delivered_revenue,0) AS delivered_revenue, IFNULL(O.dispatched_orders,0) AS dispatched_orders, IFNULL(O.dispatched_revenue,0) AS dispatched_revenue, IFNULL(O.realised_orders,0) AS realised_orders, IFNULL(O.realised_revenue,0) AS realised_revenue, IFNULL(M.marketing_spend,0) AS marketing_spend, IFNULL(O.cod_orders,0) AS cod_orders, IFNULL(O.repeat_customer_revenue,0) AS repeat_customer_revenue, IFNULL(T.mc_mp_customer_till_date,0) AS mc_mp_customer_till_date, IFNULL(T.mc_mp_sales_till_date,0) AS mc_mp_sales_till_date FROM FinalGrain G LEFT JOIN Orders O ON date(G.date) = date(O.date) AND upper(trim(G.brand)) = upper(trim(O.brand)) AND upper(trim(G.marketplace)) = upper(trim(O.marketplace)) AND upper(trim(G.marketing_channel)) = upper(trim(O.marketing_channel)) AND upper(trim(G.source)) = upper(trim(O.source)) AND upper(trim(G.channel_type)) = upper(trim(O.channel_type)) LEFT JOIN Sessions S ON date(G.date) = date(S.date) AND upper(trim(G.brand)) = upper(trim(S.brand)) AND upper(trim(G.marketplace)) = upper(trim(S.marketplace)) AND upper(trim(G.marketing_channel)) = upper(trim(S.marketing_channel)) AND upper(trim(G.source)) = upper(trim(S.source)) AND upper(trim(G.channel_type)) = upper(trim(S.channel_type)) LEFT JOIN SpendAllocated M ON date(G.date) = date(M.date) AND upper(trim(G.brand)) = upper(trim(M.brand)) AND upper(trim(G.marketplace)) = upper(trim(M.marketplace)) AND upper(trim(G.marketing_channel)) = upper(trim(M.marketing_channel)) AND upper(trim(G.source)) = upper(trim(M.source)) AND upper(trim(G.channel_type)) = upper(trim(M.channel_type)) LEFT JOIN ReturnAllocated R ON G.date = R.date AND G.brand = R.brand AND G.marketplace = R.marketplace AND G.marketing_channel = R.marketing_channel AND G.source = R.source AND G.channel_type = R.channel_type LEFT JOIN TillDateGrain T ON G.date = date(T.date) AND upper(trim(G.brand)) = upper(trim(T.brand)) AND upper(trim(G.marketplace)) = upper(trim(T.marketplace)) AND upper(trim(G.marketing_channel)) = upper(trim(T.marketing_channel)) AND upper(trim(G.source)) = upper(trim(T.source)) AND upper(trim(G.channel_type)) = upper(trim(T.channel_type)) ; CREATE OR REPLACE TABLE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_SALES_COST_SOURCE AS SELECT date, brand, marketplace, marketing_channel, source, channel_type, total_sales, total_sales_excl_cancl, sessions, transactions, revenue, total_orders, orders_excl_cancl, new_customer_orders, new_customer_orders_excl_cancl, total_new_customers, new_customers_excl_cancl, total_unique_customers, unique_customers_excl_cancl, repeat_customers, repeat_customers_excl_cancl, total_discount, total_discount_excl_cancl, total_tax, tax_excl_cancl, total_shipping_price, shipping_price_excl_cancl, new_customer_discount, new_customer_discount_excl_cancl, total_quantity, quantity_excl_cancl, return_quantity, return_value, cancelled_orders, net_orders, delivered_orders, delivered_revenue, dispatched_orders, dispatched_revenue, realised_orders, realised_revenue, marketing_spend, cod_orders, repeat_customer_revenue, mc_mp_customer_till_date, mc_mp_sales_till_date FROM PEESAFE_DB.MAPLEMONK.PEESAFE_DB_Sales_Cost_Source_intermediate;",
